// swift-tools-version:6.0
// Production Design System — Swift package (ADR 0013, 0017). At the repo root because SwiftPM
// resolves git-URL dependencies from the repository root; sources live in platforms/ios/.
//
// PDSTokens: generated by `npm run tokens:build` (packages/tokens/scripts/emit-swift.mjs) and
// committed, so consumers need no Node step. Do not edit those files by hand.
// PDSUI: SwiftUI components implementing design/contracts/ (Phase 5, ADR 0018). Its icon
// sources in Icons/ are generated by `npm run icons:swift` (ADR 0019).
//
// Platforms (ADR 0018): iOS 17; macOS 14 is the build/test host only, not a supported product
// platform. PDSTokens is pure Swift and also builds on Linux (`swift build --target PDSTokens`);
// PDSUI needs SwiftUI, so it builds and tests on macOS.
import PackageDescription

let package = Package(
    name: "PDS",
    defaultLocalization: "en",
    platforms: [
        .iOS(.v17),
        .macOS(.v14),
    ],
    products: [
        .library(name: "PDSTokens", targets: ["PDSTokens"]),
        .library(name: "PDSUI", targets: ["PDSUI"]),
    ],
    targets: [
        .target(name: "PDSTokens", path: "platforms/ios/Sources/PDSTokens"),
        .target(
            name: "PDSUI",
            dependencies: ["PDSTokens"],
            path: "platforms/ios/Sources/PDSUI",
            exclude: ["README.md"],
            resources: [.process("Resources")]
        ),
        .testTarget(
            name: "PDSUITests",
            dependencies: ["PDSUI", "PDSTokens"],
            path: "platforms/ios/Tests/PDSUITests"
        ),
    ]
)
